<?php if(!function_exists('run')){http_response_code(404);exit;} ?><div class="form-grid"><label>Preferred venue / table<select name="venue_id" required><option value="">Choose a venue</option><?php foreach(run('SELECT * FROM venues WHERE active=1 ORDER BY name')->fetchAll() as $v): ?><option value="<?= $v['id'] ?>"><?= esc($v['name']) ?> · up to <?= $v['capacity'] ?> guests</option><?php endforeach; ?></select></label><label>Package<select name="package_id"><option value="0">Custom event / inquire first</option><?php foreach(run('SELECT * FROM packages WHERE active=1 ORDER BY name')->fetchAll() as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?> · <?= money($p['price']) ?></option><?php endforeach; ?></select></label></div><p class="sample-note" style="margin:0 0 20px">If no venue is listed, the team is still configuring availability. Times are Asia/Manila; overnight events need separate arrangements.</p><button class="text-link" type="button" id="check-availability">Check selected date and time ↗</button><p id="availability-result" role="status" class="help"></p>
